mapper.select:
SELECT l.handler_note FROM finance_review_task_log l INNER JOIN finance_review_task t ON t.task_id = l.task_id WHERE l.action_type = 'DONE' AND l.handler_note IS NOT NULL AND l.handler_note != '' AND l.action_time >= #{startDate} AND l.action_time <= #{endDate}
AND t.dept_id IN #{id}
ORDER BY l.action_time DESC LIMIT 5

SELECT t.title FROM finance_review_task t WHERE t.status IN ('PENDING', 'IN_PROGRESS') AND t.severity = 'HIGH'
AND t.dept_id IN #{id}
ORDER BY t.create_time ASC LIMIT 10
